@page{size:A4;margin:17mm 16mm}*{box-sizing:border-box}body{font:11pt 'DejaVu Serif',serif;color:#111;margin:0;line-height:1.5}.kop{width:100%;border-collapse:collapse;border-bottom:3px solid #111;margin-bottom:17px}.kop td{vertical-align:middle;text-align:center;padding:0 0 10px}.kop .logo{width:75px}.kop img{max-width:67px;max-height:78px}.kop .gov{font:12pt 'DejaVu Sans',sans-serif}.kop strong{font: bold 14pt 'DejaVu Sans',sans-serif}.alamat{font-size:9pt}.title{text-align:center;font-weight:bold;text-decoration:underline;font-size:13pt;margin:12px 0 0}.nomor{text-align:center;font-size:10pt;margin:0 0 18px}.items{width:100%;border-collapse:collapse;font-size:9pt;margin:14px 0}.items th,.items td{border:1px solid #333;padding:6px;vertical-align:top;overflow-wrap:break-word}.items th{font-weight:bold;text-align:center;background:#f2f2f2}.num{text-align:right;white-space:nowrap}thead{display:table-header-group}tr{page-break-inside:avoid}.detail{width:100%;border-collapse:collapse}.detail td{padding:7px 0;vertical-align:top}.detail .label{width:30%}.sign{width:100%;margin-top:22px;page-break-inside:avoid;border-collapse:collapse;font-size:10pt}.sign td{width:33%;vertical-align:top;padding:6px}.space{height:65px}.footer{font-size:8pt;color:#777;margin-top:22px}.toolbar{background:#eef4f0;padding:15px;margin-bottom:20px;font:14px sans-serif}.toolbar a,.toolbar button{margin-right:15px;color:#155e49}.archive{border:2px solid #a33;color:#a33;padding:8px;text-align:center;font-weight:bold;margin-bottom:12px}.right{text-align:right}.no-break{page-break-inside:avoid}.notes{white-space:pre-wrap;overflow-wrap:break-word}@media print{.toolbar{display:none}} 

/* Scoped document styles also apply inside the final LPJ report. */
.lpj-document{font:10.5pt 'DejaVu Serif',serif;line-height:1.4;color:#111}
.lpj-document p{margin:9px 0}
.lpj-document table{width:100%;border-collapse:collapse}
.lpj-document .kop{border-bottom:2px solid #222;margin:0 0 13px}
.lpj-document .kop td{border:0;text-align:center;vertical-align:middle;padding:0 0 9px}
.lpj-document .kop .logo{width:72px;text-align:left}
.lpj-document .kop img{max-width:62px;max-height:70px}
.lpj-document .kop .gov{font:10.5pt 'DejaVu Sans',sans-serif}
.lpj-document .kop strong{font:bold 13pt 'DejaVu Sans',sans-serif}
.lpj-document .alamat{font-size:8.5pt}
.lpj-document .title{font:bold 12pt 'DejaVu Sans',sans-serif;text-align:center;text-decoration:underline;margin:10px 0 3px}
.lpj-document .nomor{text-align:center;font-size:9pt;margin:0 0 14px}
.lpj-document .detail{font-size:9.5pt;margin:8px 0 12px}
.lpj-document .detail td{border:0;padding:3px 0;vertical-align:top}
.lpj-document .detail .label{width:29%}
.lpj-document .recipient{text-align:left;margin:14px 0}
.lpj-document .items{font-size:8.5pt;margin:10px 0;table-layout:auto}
.lpj-document .items th,.lpj-document .items td{border:1px solid #777;padding:5px;vertical-align:top;overflow-wrap:break-word}
.lpj-document .items th{background:#ededed;text-align:center;font-family:'DejaVu Sans',sans-serif;font-size:8pt}
.lpj-document .items tr:last-child{background:#f5f5f5}
.lpj-document .inspection tr:last-child{background:white}
.lpj-document .num{text-align:right;white-space:nowrap}
.lpj-document .center{text-align:center}
.lpj-document .amount-band{background:#ededed;margin:10px 0 5px;font:bold 10pt 'DejaVu Sans',sans-serif}
.lpj-document .amount-band td{border:0;border-top:1px solid #777;border-bottom:1px solid #777;padding:8px}
.lpj-document .terbilang{font-size:9pt;font-style:italic;margin:5px 0 12px}
.lpj-document h4{font:bold 9pt 'DejaVu Sans',sans-serif;margin:13px 0 6px}
.lpj-document .no-break{page-break-inside:avoid}
.lpj-document .right{text-align:right}
.lpj-document .sign{margin-top:12px;table-layout:fixed;font-size:9pt;page-break-inside:avoid}
.lpj-document .sign td{border:0;vertical-align:top;text-align:center;padding:4px;width:auto;overflow-wrap:break-word}
.lpj-document .space{height:58px}
.lpj-document .footer{font:7pt 'DejaVu Sans',sans-serif;color:#666;border-top:1px solid #ccc;padding-top:6px;margin-top:16px}
.lpj-document .notes{font-size:9pt;white-space:pre-wrap;overflow-wrap:break-word}
.lpj-document thead{display:table-header-group}
.lpj-document tr{page-break-inside:avoid}
